/**
 * Экран броска S10: два кубика падают поверх текста, катятся и показывают число.
 *
 * Кубики — настоящие 3D-модели на прозрачном canvas поверх страницы
 * (`src/three/diceScene.ts`), панель с итогом живёт ниже и не закрывает бросок.
 * Если WebGL недоступен или модуль не поднялся, работает прежний DOM-вариант:
 * экран броска обязан показываться на любом устройстве.
 */

import { useEffect, useRef, useState } from 'preact/hooks';
import type { JSX } from 'preact';

import { Button } from '../components.tsx';
import { SKILL_NAMES } from '../../engine/types.ts';
import type { GameState } from '../../engine/engine.ts';

type Roll = NonNullable<GameState['lastRoll']>;

declare global {
  interface Window {
    /** Состояние 3D-броска: значения кубиков и фаза (для тестов и отладки). */
    __NARNIA_DICE__?: { values: number[]; phase: 'tumble' | 'sum' | 'result' };
  }
}

function hasWebGL(): boolean {
  try {
    const canvas = document.createElement('canvas');
    return Boolean(canvas.getContext('webgl2') ?? canvas.getContext('webgl'));
  } catch {
    return false;
  }
}

export function DiceOverlay(props: {
  roll: Roll;
  speed: 'normal' | 'fast';
  onClose: () => void;
}): JSX.Element {
  const { roll, speed } = props;
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [phase, setPhase] = useState<'tumble' | 'sum' | 'result'>('tumble');
  const [mode, setMode] = useState<'3d' | 'dom'>(hasWebGL() ? '3d' : 'dom');
  const [faces, setFaces] = useState<[number, number]>([1, 1]);
  const timers = useRef<number[]>([]);

  // --- 3D-кубики поверх текста ---
  useEffect(() => {
    if (mode !== '3d') return;
    let disposed = false;
    let scene: { dispose: () => void; resize: (w: number, h: number, ratio?: number) => void; roll: (values: number[], seed?: number) => void } | null = null;
    let detach = (): void => {};

    (async () => {
      try {
        const module = await import('../../three/diceScene.ts');
        if (disposed || !canvasRef.current) return;
        scene = new module.DiceScene(canvasRef.current, {
          fall: speed === 'fast' ? 0.75 : 1.5,
          hold: speed === 'fast' ? 0.2 : 0.5,
          onSettled: () => {
            setPhase('sum');
            window.__NARNIA_DICE__ = { values: roll.dice, phase: 'sum' };
            const sumMs = speed === 'fast' ? 140 : 700;
            timers.current.push(window.setTimeout(() => {
              setPhase('result');
              window.__NARNIA_DICE__ = { values: roll.dice, phase: 'result' };
            }, sumMs));
          },
        });
        const resize = (): void => {
          scene?.resize(window.innerWidth, window.innerHeight, window.devicePixelRatio || 1);
        };
        resize();
        window.addEventListener('resize', resize);
        detach = () => window.removeEventListener('resize', resize);
        window.__NARNIA_DICE__ = { values: roll.dice, phase: 'tumble' };
        scene.roll(roll.dice, 1 + roll.total * 31 + roll.dice[0] * 7 + roll.dice[1]);
      } catch {
        setMode('dom');
      }
    })();

    return () => {
      disposed = true;
      detach();
      scene?.dispose();
      delete window.__NARNIA_DICE__;
    };
  }, [mode, roll, speed]);

  // --- запасной DOM-вариант (без WebGL) ---
  useEffect(() => {
    if (mode !== 'dom') return;
    const tumbleMs = speed === 'fast' ? 220 : 1000;
    const sumMs = speed === 'fast' ? 120 : 650;
    const startedAt = Date.now();
    const spin = window.setInterval(() => {
      if (Date.now() - startedAt >= tumbleMs) {
        window.clearInterval(spin);
        setFaces(roll.dice);
        setPhase('sum');
        timers.current.push(window.setTimeout(() => setPhase('result'), sumMs));
      } else {
        setFaces([1 + Math.floor(Math.random() * 6), 1 + Math.floor(Math.random() * 6)]);
      }
    }, 70);
    return () => window.clearInterval(spin);
  }, [mode, roll, speed]);

  useEffect(() => () => {
    for (const timer of timers.current) window.clearTimeout(timer);
    timers.current = [];
  }, []);

  const skillNote = roll.skill ? SKILL_NAMES[roll.skill] : 'без навыка';

  return (
    <div class="overlay overlay--dice">
      {mode === '3d' && <canvas ref={canvasRef} class="dice-3d" aria-hidden="true" />}

      <div class="overlay__panel dice-panel">
        <h3 class="overlay__title">Бросок кубиков</h3>

        {mode === 'dom' && (
          <div class={`dice dice--${phase}`} aria-live="polite">
            <div class="dice__die">{(phase === 'tumble' ? faces : roll.dice)[0]}</div>
            <div class="dice__die">{(phase === 'tumble' ? faces : roll.dice)[1]}</div>
          </div>
        )}
        {mode === '3d' && phase === 'tumble' && (
          <p class="dice-panel__line">Кубики катятся…</p>
        )}

        {phase !== 'tumble' && (
          <p class="dice-panel__line">
            {roll.dice[0]} + {roll.dice[1]} = <b>{roll.total}</b>
            {roll.skill ? `, ${skillNote} ${roll.skillValue >= 0 ? '+' : ''}${roll.skillValue}` : `, ${skillNote}`}
          </p>
        )}
        {phase === 'result' && (
          <p class="dice-panel__line dice-panel__result">
            Итог <b>{roll.result}</b> — переход выполнен
          </p>
        )}

        <Button kind={phase === 'result' ? 'primary' : 'ghost'} onClick={props.onClose}>
          {phase === 'result' ? 'Дальше' : 'Пропустить'}
        </Button>
      </div>
    </div>
  );
}
